// docs/RESEARCH_NOTE.md -> docs/RESEARCH_NOTE.pdf, typeset in headless Chromium.
// The Markdown (and its SVG figures) are generated by `uv run wsl report docs`; this only lays
// them out for print. Usage: node scripts/note-pdf.mjs
import { readFileSync, rmSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import { marked } from "marked";
import { chromium } from "playwright";

const here = dirname(fileURLToPath(import.meta.url));
const docs = resolve(here, "../../docs");
const fonts = resolve(here, "../node_modules/@fontsource");
const md = readFileSync(resolve(docs, "RESEARCH_NOTE.md"), "utf8");
const font = (family, file, weight, style = "normal") =>
  `@font-face{font-family:"${family}";font-weight:${weight};font-style:${style};src:url("${pathToFileURL(resolve(fonts, file)).href}") format("woff2")}`;

const html = `<!doctype html><html lang="en"><head><meta charset="utf-8"><title>How the World Moves Canada</title><style>
${font("IBM Plex Sans", "ibm-plex-sans/files/ibm-plex-sans-latin-400-normal.woff2", 400)}
${font("IBM Plex Sans", "ibm-plex-sans/files/ibm-plex-sans-latin-400-italic.woff2", 400, "italic")}
${font("IBM Plex Sans", "ibm-plex-sans/files/ibm-plex-sans-latin-600-normal.woff2", 600)}
${font("IBM Plex Mono", "ibm-plex-mono/files/ibm-plex-mono-latin-400-normal.woff2", 400)}
@page { size: Letter; margin: 20mm 19mm 22mm 19mm; }
body { font: 10.4pt/1.5 "IBM Plex Sans", "Helvetica Neue", Arial, sans-serif; color: #121722; }
h1 { font-size: 19pt; line-height: 1.2; margin: 0 0 6pt; font-weight: 600; letter-spacing: -0.01em; }
h1 + p { color: #485164; font-size: 9pt; margin-bottom: 14pt; }
h2 { font-size: 13pt; margin: 16pt 0 5pt; font-weight: 600; break-after: avoid; }
h3 { font-size: 11pt; margin: 12pt 0 4pt; font-weight: 600; break-after: avoid; }
p, li { margin: 0 0 6pt; orphans: 3; widows: 3; }
ul { padding-left: 15pt; margin: 0 0 8pt; }
img { display: block; width: 100%; max-width: 100%; margin: 8pt 0 2pt; break-inside: avoid; }
p:has(> img) { break-inside: avoid; break-after: avoid; margin: 0; }
p:has(> img) + p em { display: block; font-size: 8.6pt; color: #485164; margin-bottom: 10pt; }
code { font: 8.8pt "IBM Plex Mono", Menlo, monospace; background: #f3f5f8; padding: 0 2pt; border-radius: 2pt; }
h2#references + ul li, h2:last-of-type ~ ul li { font-size: 8.8pt; margin-bottom: 3pt; }
a { color: #1c5cab; text-decoration: none; }
</style></head><body>${marked.parse(md)}</body></html>`;

const tmp = resolve(docs, ".RESEARCH_NOTE.print.html");
writeFileSync(tmp, html);
const browser = await chromium.launch();
try {
  const page = await browser.newPage();
  await page.goto(pathToFileURL(tmp).href, { waitUntil: "networkidle" });
  await page.evaluate(() => document.fonts.ready);
  await page.pdf({
    path: resolve(docs, "RESEARCH_NOTE.pdf"),
    format: "Letter",
    printBackground: true,
    displayHeaderFooter: true,
    headerTemplate: "<span></span>",
    footerTemplate: `<div style="width:100%;font:8px Helvetica,Arial,sans-serif;color:#5d6677;padding:0 19mm;display:flex;justify-content:space-between"><span>World Shock Lab · How the World Moves Canada</span><span><span class="pageNumber"></span> / <span class="totalPages"></span></span></div>`,
    margin: { top: "20mm", bottom: "22mm", left: "19mm", right: "19mm" },
  });
  const pages = await page.evaluate(() => Math.ceil(document.body.scrollHeight / (11 * 96 - 42 * 3.78)));
  console.log(`wrote docs/RESEARCH_NOTE.pdf (about ${pages} pages)`);
} finally {
  await browser.close();
  if (!process.env.KEEP_HTML) rmSync(tmp, { force: true });
}
